const verify = (body: Buffer, signature: string): Stripe.Event => {
  const secrets = [keys.stripeWebhookSecret, keys.stripeConnectWebhookSecret].filter(Boolean);
  let lastError: unknown;
  for (const secret of secrets) {
    try {
